<?php
declare(strict_types=1);
final class ApiError extends RuntimeException { public function __construct(string $message,public int $status=400){parent::__construct($message);} }
function cfg():array { static $c; if($c===null){$file=(PHP_SAPI==='cli'&&getenv('PINA_CONFIG'))?getenv('PINA_CONFIG'):__DIR__.'/config.php';if(!is_file($file))throw new ApiError('Сайт ещё не настроен',503);$c=require $file;}return $c; }
function db():PDO { static $p; if(!$p){$c=cfg()['db'];$p=new PDO('mysql:host='.$c['host'].';port='.($c['port']??3306).';dbname='.$c['name'].';charset=utf8mb4',$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$p->exec("SET time_zone = '+00:00'");}return $p; }
function query(string $sql,array $args=[]):PDOStatement {$s=db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array {$r=query($sql,$args)->fetch();return $r?:null;}
function rows(string $sql,array $args=[]):array {return query($sql,$args)->fetchAll();}
function now():string{return gmdate('Y-m-d H:i:s');}
function iso(?string $s):?string{return $s?str_replace(' ','T',$s).'Z':null;}
function json_out(mixed $data,int $status=200):never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function input():array {if(PHP_SAPI==='cli'&&defined('PINA_LIBRARY_ONLY')&&isset($GLOBALS['test_input']))return $GLOBALS['test_input'];if((int)($_SERVER['CONTENT_LENGTH']??0)>32768)throw new ApiError('Слишком большой запрос');$s=file_get_contents('php://input');try{$d=json_decode($s?:'{}',true,512,JSON_THROW_ON_ERROR);}catch(JsonException){throw new ApiError('Некорректный JSON');}if(!is_array($d)||array_is_list($d)&&count($d)>0)throw new ApiError('Ожидается объект JSON');return $d;}
function txt(array $d,string $key,int $max=5000,bool $required=true):string {$v=$d[$key]??'';if(!is_string($v))throw new ApiError('Проверьте поле '.$key);$v=trim($v);if(($required&&$v==='')||mb_strlen($v)>$max)throw new ApiError('Проверьте поле '.$key);return $v;}
function minor(mixed $value,int $limit=100000000):int {$s=(string)$value;if(!preg_match('/^\d{1,10}(?:\.\d{1,2})?$/D',$s))throw new ApiError('Укажите сумму с точностью до копейки');$parts=explode('.',$s);$n=(int)$parts[0]*100+(int)str_pad($parts[1]??'',2,'0');if($n<1||$n>$limit)throw new ApiError('Сумма выходит за допустимые лимиты');return $n;}
function request_key(array $d):string {$k=txt($d,'key',36);if(!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iD',$k))throw new ApiError('Некорректный ключ запроса');return strtolower($k);}
function password_rules(string $p):void {if(strlen($p)<12||strlen($p)>200||preg_match('/^\d+$/D',$p))throw new ApiError('Пароль должен содержать от 12 до 200 символов и не состоять только из цифр');}
function next_client_id(int $previous):int {return $previous===0?1000:(intdiv($previous,13)+1)*13;}
function allocate(string $name):int {$r=one('SELECT value FROM pm_counters WHERE name=? FOR UPDATE',[$name]);if(!$r)throw new RuntimeException('Missing counter');$prev=(int)$r['value'];$next=$name==='client'?next_client_id($prev):($prev===0?1000:$prev+1);query('UPDATE pm_counters SET value=? WHERE name=?',[$next,$name]);return $next;}
function transact(callable $f):mixed {db()->beginTransaction();try{$r=$f();db()->commit();return $r;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
function audit(?int $actor,string $action,int|string $ref,array $data=[]):void {query('INSERT INTO pm_audit(actor_id,action,object_ref,details_json,created_at) VALUES(?,?,?,?,?)',[$actor,$action,(string)$ref,json_encode($data,JSON_THROW_ON_ERROR),now()]);}
function notify(int $client,int $author,string $body,?int $op=null):void {query('INSERT INTO pm_messages(client_id,operation_id,author_id,body,created_at) VALUES(?,?,?,?,?)',[$client,$op,$author,$body,now()]);}
function ledger(int $op,string $event,int $balance,int $reserve,int $actor):void {query('INSERT INTO pm_ledger(operation_id,event,balance_delta,reserved_delta,actor_id,created_at) VALUES(?,?,?,?,?,?)',[$op,$event,$balance,$reserve,$actor,now()]);}
function throttle(string $scope,string $identity='',int $limit=10):void {foreach(array_unique([$_SERVER['REMOTE_ADDR']??'unknown',$identity?:($_SERVER['REMOTE_ADDR']??'unknown')]) as $target){$key=hash('sha256',$scope.':'.$target.':'.intdiv(time(),600));query('INSERT INTO pm_rate_buckets(bucket,attempts,created_at) VALUES(?,1,?) ON DUPLICATE KEY UPDATE attempts=attempts+1',[$key,now()]);$r=one('SELECT attempts FROM pm_rate_buckets WHERE bucket=?',[$key]);if((int)$r['attempts']>$limit)throw new ApiError('Слишком много попыток. Повторите через 10 минут.',429);}}
function session_init():void {if(session_status()!==PHP_SESSION_ACTIVE){ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');ini_set('session.gc_maxlifetime','43200');session_name('pina_session');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>!(cfg()['debug']??false),'httponly'=>true,'samesite'=>'Lax']);session_start();}if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));if(!empty($_SESSION['last'])&&time()-$_SESSION['last']>43200){$_SESSION=['csrf'=>bin2hex(random_bytes(32))];}$_SESSION['last']=time();}
function current_client(bool $required=true,bool $staff=false):?array {$c=null;if(isset($_SESSION['client']))$c=one('SELECT * FROM pm_clients WHERE id=?',[(int)$_SESSION['client']]);if($c&&(int)($c['auth_version'])!==(int)($_SESSION['auth_version']??0)){$c=null;unset($_SESSION['client']);}if(!$c&&$required)throw new ApiError('Войдите в кабинет',401);if($staff&&(!$c||!(int)$c['is_staff']))throw new ApiError('Недостаточно прав',403);return $c;}
function csrf_check():void {$token=$_SERVER['HTTP_X_CSRFTOKEN']??'';if(!is_string($token)||!hash_equals($_SESSION['csrf']??'',$token))throw new ApiError('Сессия устарела. Обновите страницу.',403);if(isset($_SERVER['HTTP_ORIGIN'])&&rtrim($_SERVER['HTTP_ORIGIN'],'/')!==rtrim(cfg()['base_url'],'/'))throw new ApiError('Недопустимый источник запроса',403);}
function client_json(array $c):array{return ['id'=>(int)$c['id'],'email'=>$c['email'],'balance'=>(int)$c['balance_minor'],'reserved'=>(int)$c['reserved_minor'],'created'=>iso($c['created_at'])];}
function service_json(array $s):array{return ['id'=>$s['code'],'name'=>$s['name'],'desc'=>$s['description'],'instructions'=>$s['instructions'],'conditions'=>$s['conditions_text'],'type'=>$s['product'],'cat'=>$s['category'],'status'=>$s['status'],'feeBps'=>(int)$s['fee_bps'],'min'=>(int)$s['min_minor'],'max'=>(int)$s['max_minor'],'regions'=>json_decode($s['regions_json'],true),'version'=>(string)$s['version']];}
function op_select():string{return 'SELECT o.*,c.email,a.email AS assigned_email FROM pm_operations o JOIN pm_clients c ON c.id=o.client_id LEFT JOIN pm_clients a ON a.id=o.assigned_to';}
function op_json(array $o):array {$s=json_decode($o['snapshot_json'],true);$messages=rows('SELECT m.*,c.is_staff FROM pm_messages m JOIN pm_clients c ON c.id=m.author_id WHERE m.operation_id=? ORDER BY m.id',[(int)$o['number']]);return ['id'=>(int)$o['number'],'clientId'=>(int)$o['client_id'],'email'=>$o['email']??'','kind'=>$o['kind'],'status'=>$o['status'],'amount'=>(int)$o['amount_minor'],'fee'=>(int)$o['fee_minor'],'total'=>(int)$o['total_minor'],'service'=>$s['name']??'','serviceId'=>$s['code']??'','cashAddress'=>$s['cashAddress']??'','product'=>$s['product']??'','conditions'=>$s['conditions']??'','instructions'=>$s['instructions']??'','recipient'=>$o['recipient'],'region'=>$o['region'],'bankref'=>$o['bank_reference']??'','assigned'=>$o['assigned_email']??'','result'=>$o['result_text'],'created'=>iso($o['created_at']),'updated'=>iso($o['updated_at']),'messages'=>array_map(fn($m)=>['id'=>(int)$m['id'],'text'=>$m['body'],'staff'=>(bool)$m['is_staff'],'created'=>iso($m['created_at'])],$messages)];}
function get_op(int $id):array {$o=one(op_select().' WHERE o.number=?',[$id]);if(!$o)throw new ApiError('Заявка не найдена',404);return op_json($o);}
function legal_data():array {static $l;return $l??=json_decode(file_get_contents(__DIR__.'/legal.json'),true,512,JSON_THROW_ON_ERROR);}
function site_settings():array {
 $c=cfg();$r=one("SELECT value FROM pm_meta WHERE name='site_settings'");
 $s=$r?json_decode($r['value'],true):[];
 return ['cashEnabled'=>(bool)($s['cashEnabled']??($c['cash_enabled']??false)),'cashAddress'=>(string)($s['cashAddress']??($c['cash_address']??''))];
}
